device: xc7a35t-cpg236
carry:
  inc (8 bits) -> 2 x CARRY4
io:
  clk (1 bits) -> IBUF at pin W5 as LVCMOS33
  rst (1 bits) -> IBUF at pin U18 as LVCMOS33
  sw (4 bits) -> IBUF at pin V17,V16,W16,W17
  led (4 bits) -> OBUF at pin U16,E19,U19,V19
clocks:
  clk (12 flip-flops) -> BUFG
logic:
  5 LUTs, depth 1
netlist:
  1 x BUFG
  2 x CARRY4
  4 x FDCE
  7 x FDRE
  1 x FDSE
  6 x IBUF
  5 x LUT6
  4 x OBUF
